css:
:root{color-scheme:dark;--ink:#efe6d2;--muted:#b5a78a;--acc:#00a6fb;--acc2:#6fd3ff;--acc3:#05689c;--brass:#d9a441;--brass2:#f3cf7a;--brass3:#8a6224;--brass4:#4d3612;--oak:#2a1a10;--oak2:#3d2616;--oak3:#5a3a22;--night:#07090c;--paper:#f1e9d6;--glass:#0b1a24;--red:#d6312a;--green:#46c37b;--line:#ffffff17;--panel:#160d08;--cond:"DIN Condensed","Bahnschrift Condensed","Barlow Condensed","Roboto Condensed","Arial Narrow","DejaVu Sans Condensed",sans-serif;--mono:"SF Mono",Menlo,"DejaVu Sans Mono",Consolas,monospace;--serif:Georgia,"Times New Roman",serif}
*{box-sizing:border-box}
button,a{-webkit-tap-highlight-color:transparent}
button{font:inherit;color:inherit;cursor:pointer;border:0;background:none}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--acc);outline-offset:3px}
button:disabled{opacity:.35;cursor:not-allowed}
button:hover:not(:disabled){filter:brightness(1.15)}
a{color:var(--acc2)}
.eyebrow{font-size:10px;letter-spacing:2px;color:#c9a45a;font-weight:600;line-height:1.8;margin:0;font-family:var(--mono)}
#celebration{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:5}
.coin{position:absolute;animation:fall 2.4s ease-in both}
dialog{border:1px solid var(--brass3);background:repeating-linear-gradient(92deg,#ffffff05 0 2px,#00000010 2px 5px),linear-gradient(#2a1a10,#160d08);color:var(--ink);border-radius:6px;width:min(780px,94vw);max-height:86vh;padding:24px 28px;box-shadow:0 35px 120px #000c,inset 0 0 0 1px #f3cf7a1f;border-top:6px solid var(--acc)}
dialog::backdrop{background:#030507d6;backdrop-filter:blur(8px)}
.modal-head{display:flex;align-items:center;justify-content:space-between}
.modal-head button{font-size:30px;color:#c9a45a;min-width:44px;min-height:44px}
dialog h2{font:700 32px var(--serif);color:var(--brass2);margin:12px 0;letter-spacing:.5px;text-shadow:0 1px 0 #000}
dialog p,dialog li{font-size:13px;color:#e0d6bf;line-height:1.75;font-family:"Helvetica Neue",Arial,sans-serif}
dialog h3{font:700 12px var(--mono);letter-spacing:1.5px;color:var(--acc2);margin-top:26px}
dialog code{color:var(--brass2);font-size:11px;word-break:break-all}
.cta{background:linear-gradient(#f3cf7a,#d9a441 55%,#8a6224);color:#1b1006;padding:13px 20px;border-radius:4px;font-weight:800;font-size:14px;letter-spacing:1px;margin:12px 8px 0 0;display:inline-flex;align-items:center;min-height:44px;text-decoration:none;font-family:var(--cond);box-shadow:0 3px 0 #3a2508}
.outline{border:1px solid var(--brass3);padding:12px 18px;border-radius:4px;font-size:12px;margin:8px 8px 0 0;display:inline-flex;align-items:center;min-height:44px;font-family:var(--mono);background:#00000033}
.paytable{width:100%;border-collapse:collapse;font-size:12px}
.paytable th{color:#b5a78a;font-weight:400;font-size:10px;text-align:left;letter-spacing:1px;font-family:var(--mono)}
.paytable td,.paytable th{padding:9px;border-bottom:1px solid #ffffff12;vertical-align:middle}
.pay-icon{width:34px;height:34px;vertical-align:middle;margin-right:8px}
.rule-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.line-card{border:1px solid #f3cf7a22;padding:8px;text-align:center;font-size:10px;color:#b5a78a;border-radius:4px;background:#0b1a2455}
.line-card svg{width:100%;height:32px}
.stat-cards{display:flex;gap:10px;margin:18px 0;flex-wrap:wrap}
.stat-cards>div{padding:14px 14px 14px 30px;border:1px solid var(--brass3);border-radius:3px;flex:1;background:linear-gradient(#f1e9d6,#e2d6b6);min-width:150px;position:relative;box-shadow:0 2px 0 #000a}
.stat-cards>div::before{content:"";position:absolute;left:10px;top:50%;width:9px;height:9px;margin-top:-5px;border-radius:50%;background:radial-gradient(#07090c 55%,#8a6224 60%);box-shadow:inset 0 1px 2px #000}
.stat-cards span{display:block;font-size:10px;color:#5b4a2c;font-family:var(--mono);letter-spacing:.6px}
.stat-cards strong{display:block;font-size:26px;margin-top:6px;font-weight:700;color:#2a1a10;font-family:var(--serif)}
.setting{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:12px 0;border-bottom:1px solid #ffffff15;font-size:13px;min-height:44px}
.setting input[type=range]{width:45%;accent-color:var(--acc)}
.setting input[type=checkbox]{accent-color:var(--acc);width:22px;height:22px}
.history-wrap{max-height:330px;overflow:auto}
.labtag{background:var(--acc);color:#04121c;padding:1px 5px;border-radius:3px;font-size:10px}
.fine{font-size:11px!important;color:#a49a82!important}
.hash{font:12px/1.6 ui-monospace,Menlo,Consolas,monospace;word-break:break-all;color:#efe6d2;background:#07090c;border:1px solid #ffffff14;border-radius:4px;padding:12px;white-space:pre-wrap}
ul.posts{padding-left:18px}ul.posts li{margin:4px 0}
.error-panel{max-width:520px;padding:0 24px;text-align:center;line-height:1.7}
.error-panel h2{font-weight:400;font-size:24px;color:var(--brass2);margin:0 0 10px}
.error-panel p{font-size:13px;color:#e0d6bf;margin:6px 0}
.noscript{position:fixed;inset:0;z-index:60;margin:0;display:flex;align-items:center;justify-content:center;background:#07090c;color:#eee}
@keyframes rotate{to{transform:rotate(360deg)}}
@keyframes pulse{50%{box-shadow:0 0 16px #00a6fb88}}
@keyframes fall{0%{transform:translateY(-30px) rotate(0);opacity:0}10%{opacity:1}100%{transform:translateY(100vh) rotate(540deg);opacity:0}}
@keyframes lensSweep{0%{transform:translate(-22px,10px) scale(.92)}50%{transform:translate(22px,-8px) scale(1.04)}100%{transform:translate(-22px,10px) scale(.92)}}
.coin.inf{font-size:26px;color:var(--brass2);text-shadow:0 0 12px #00a6fb;font-family:var(--serif);font-weight:700}
/* Rarity tags, sat tables and check marks (SATS, RARITY and HOLDER POT panels) */
.rc{display:inline-block;border-radius:3px;padding:2px 7px;font:700 10px var(--mono);letter-spacing:1px;color:#07090c;background:#00a6fb;border:1px solid #0006;white-space:nowrap;margin:0 4px 2px 0}
.rc-mythic{background:linear-gradient(90deg,#fff,#bfe9ff)}.rc-legendary{background:#ff9bd2}.rc-epic{background:#ffd23f}.rc-rare{background:#5fd0ff}.rc-uncommon{background:#8be28b}
.rc-black{background:#1c1f24;color:#e9eef2;border-color:#e9eef2}.rc-palindrome{background:#c79bff}.rc-vintage{background:#d8b07a}.rc-nakamoto{background:#e8e3d3}.rc-pizza{background:#ff8a3d}.rc-block9{background:#7fe3d0}.rc-range{background:#00a6fb}.rc-common{background:#8a8f94}
.sat-sec{margin-top:22px}.sat-sec h3{display:flex;align-items:center;gap:8px;margin:0 0 4px}.sat-sec h3 img{width:30px;height:30px}
.sat-sec p.what{margin:0 0 6px;font-size:12px;color:#c9bfa6}
.sat-table{width:100%;border-collapse:collapse;font-size:12px}.sat-table td,.sat-table th{padding:7px 8px;border-bottom:1px solid #ffffff12;vertical-align:top;text-align:left}
.sat-table th{font:400 10px var(--mono);letter-spacing:1px;color:#b5a78a}.sat-table .num{font:700 13px var(--mono);color:var(--brass2);white-space:nowrap}.sat-table .nm{font:11px var(--mono);color:#b5a78a;word-break:break-all}
.sat-table .st{font-size:11px;color:#c9bfa6}.sat-table a.chk{display:inline-flex;align-items:center;min-height:44px;padding:0 8px;margin:-8px 0}
.vchip{display:inline-block;border:1px solid var(--brass3);color:#c9a45a;border-radius:3px;padding:1px 6px;font:10px var(--mono);letter-spacing:.6px;white-space:nowrap}.vchip.ok{border-color:var(--green);color:#9cf0bd}
.defs{display:grid;grid-template-columns:auto 1fr;gap:6px 12px;margin:10px 0;align-items:start}.defs dt{margin:0}.defs dd{margin:0;font-size:12px;color:#e0d6bf;line-height:1.55}
.ribbon{display:inline-block;background:#3a1010;color:#ffb3aa;border:1px solid #d6312a;border-radius:3px;padding:1px 6px;font:700 10px var(--mono);letter-spacing:.8px}
/* Bonus Lab */
.lab-list{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin:12px 0}
.lab-item{display:flex;gap:10px;align-items:center;border:1px solid #8a622466;border-radius:4px;padding:8px 10px;min-height:52px;cursor:pointer;background:#07090c}
.lab-item input{accent-color:var(--acc);width:20px;height:20px;flex:0 0 auto}.lab-item b{display:block;font-size:14px;color:var(--brass2);font-family:var(--cond);letter-spacing:.5px}.lab-item small{display:block;font-size:11px;color:#a49a82}
.lab-item:has(input:checked){border-color:var(--acc);background:#0b1a24}
.lab-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:8px 0;font-size:12px;color:#e0d6bf}
.lab-row select,.lab-row input[type=number]{background:#07090c;color:#efe6d2;border:1px solid var(--brass3);border-radius:4px;min-height:44px;padding:0 8px;font:inherit;margin-left:6px}
.lab-row input[type=number]{width:110px}.lab-row .chk{display:flex;gap:6px;align-items:center;min-height:44px}.lab-row .chk input{width:20px;height:20px;accent-color:var(--acc)}
.test-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.test-grid button{border:1px solid var(--brass3);border-radius:4px;padding:12px 8px;color:#efe6d2;font-size:12px;min-height:44px;background:#07090c}

:root{--bg:#07090c;--barh:150px;--safe-t:env(safe-area-inset-top,0px);--safe-b:env(safe-area-inset-bottom,0px);--safe-l:env(safe-area-inset-left,0px);--safe-r:env(safe-area-inset-right,0px)}
html,body{margin:0;height:100%;overflow:hidden;background:var(--bg)}
body{display:flex;flex-direction:column;color:var(--ink);font-family:"Helvetica Neue",Arial,sans-serif;-webkit-user-select:none;user-select:none}
#stage{position:relative;flex:1 1 auto;min-height:0;display:flex;flex-direction:column;align-items:stretch;justify-content:center;background:radial-gradient(ellipse at 50% 35%,#0f2431,#07090c 70%);touch-action:manipulation;padding:var(--safe-t) var(--safe-r) 0 var(--safe-l)}
#view{width:100%;flex:1 1 auto;min-height:0;height:0;object-fit:contain;display:block;touch-action:manipulation}
#statusLine{position:static;margin:0;flex:0 0 auto;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font:11px var(--mono);letter-spacing:1.2px;color:var(--acc2);pointer-events:none;text-shadow:0 0 8px #000;padding:0 12px 6px}
.side-meters{position:absolute;top:calc(8px + var(--safe-t));left:calc(8px + var(--safe-l));font:10px var(--mono);letter-spacing:1.2px;color:#b5a78a;display:flex;gap:14px;pointer-events:none;flex-wrap:wrap}.side-meters b{color:var(--acc2);font-weight:400;font-variant-numeric:tabular-nums}
#fsbar{flex:0 0 auto;background:linear-gradient(#f3cf7a,#8a6224) top/100% 3px no-repeat,repeating-linear-gradient(88deg,#ffffff06 0 2px,#00000012 2px 6px),linear-gradient(#3d2616,#1d1109);border-top:1px solid #000;padding:12px calc(10px + var(--safe-r)) calc(8px + var(--safe-b)) calc(10px + var(--safe-l));display:flex;flex-direction:column;gap:8px;z-index:3;box-shadow:0 -10px 30px #0008}
#featureBar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;background:linear-gradient(#f1e9d6,#e2d6b6);color:#2a1a10;border:1px solid var(--brass3);border-radius:4px;padding:8px 12px;box-shadow:inset 0 0 0 3px #f1e9d6,inset 0 0 0 4px #8a622455}
#featureBar .eyebrow{color:#6a4f1c}
#featureBar[hidden]{display:none}.fb-head{display:flex;flex-direction:column;gap:2px;min-width:150px;flex:0 1 260px}.fb-head strong{font:700 19px var(--serif);color:#2a1a10;letter-spacing:.3px}.fb-head span:last-child{font-size:12px;color:#4d3612;line-height:1.35}
#fbBody{display:flex;gap:6px;align-items:center;flex-wrap:wrap;flex:1 1 auto;justify-content:flex-end}
.pick{width:44px;height:44px;border:1px solid #000;border-radius:4px;color:var(--brass2);background:linear-gradient(#5a3a22,#2a1a10);font:800 16px var(--cond)}.pick.picked{background:#0b1a24;color:var(--acc2);border-color:var(--acc)}
.bar-cta{min-height:44px;background:linear-gradient(#4a301c,#1d1109);color:var(--brass2);padding:0 18px;border-radius:4px;font:800 15px var(--cond);letter-spacing:1px;box-shadow:0 3px 0 #000;border:1px solid #000}.bar-cta.ghost{background:none;color:#4d3612;border:1px solid #6a4f1c;box-shadow:none}
.row{display:flex;gap:8px;align-items:stretch}
.row.main{align-items:center}.row.menu{overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;-webkit-overflow-scrolling:touch}.row.menu::-webkit-scrollbar{display:none}
.read{display:flex;flex-direction:column;justify-content:center;min-width:0;padding:0 10px;border-left:1px solid var(--line)}.read:first-child{border-left:0;padding-left:2px}
.read label{font:9px var(--mono);letter-spacing:1.3px;color:#c9a45a;margin:0 0 3px;white-space:nowrap}.read strong{font:700 26px var(--serif);letter-spacing:.3px;font-variant-numeric:tabular-nums;white-space:nowrap}.read small{font:9px var(--mono);letter-spacing:1px;color:#b5a78a}
.read.win strong{color:var(--brass2)}
.stepper{display:flex;align-items:center;gap:6px}.stepper strong{font-size:24px;min-width:44px;text-align:center}.stepper button{border:1px solid var(--brass3);border-radius:50%;width:44px;height:44px;color:var(--brass2);font-size:20px;background:radial-gradient(#5a3a22,#1d1109)}
.deck{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-width:68px;min-height:44px;padding:4px 8px;border:1px solid var(--brass3);border-radius:4px;background:linear-gradient(#4a301c,#24150c);flex:0 0 auto;box-shadow:inset 0 1px 0 #f3cf7a22}.deck b{font:800 13px var(--cond);letter-spacing:1px;color:var(--brass2);white-space:nowrap}.deck i{font-style:normal;font-size:9px;color:#b5a78a;white-space:nowrap;font-family:var(--mono)}
.deck.vol{padding:0 8px}.deck.vol b{margin-top:2px}.deck.vol input{width:96px;height:44px;accent-color:var(--acc);margin:-10px 0 -8px}
.deck[aria-pressed=true]{border-color:var(--acc);background:#0b1a24}.deck[aria-pressed=true] b{color:#d8f2ff}
.deck.hot{border-color:var(--acc2);background:#0b2a40;animation:pulse 1.4s ease-in-out infinite}.deck[hidden]{display:none}
.spin{margin-left:auto;background:radial-gradient(circle at 40% 30%,#fbe7a8,#d9a441 45%,#8a6224);color:#1b1006;min-width:170px;min-height:58px;padding:4px 18px;border-radius:30px;box-shadow:0 4px 0 #3a2508,0 0 30px #00a6fb55;display:flex;flex-direction:column;align-items:center;justify-content:center;flex:0 0 auto;position:relative;border:2px solid var(--brass2)}
.spin #spinText{font:800 20px var(--cond);letter-spacing:3px}.spin small{font-size:9px;letter-spacing:1px;opacity:.8;margin:0;font-family:var(--mono)}.spin .spin-icon{position:absolute;right:14px;top:6px}.spin:active{transform:translateY(3px);box-shadow:0 1px 0 #3a2508}.spin.spinning .spin-icon{animation:rotate .7s linear infinite}.spin.small #spinText{font-size:16px;letter-spacing:1px}
#fsExit{border-color:var(--acc)}body:not(.fs-on) #fsExit{display:none}body.fs-on #fsBtn{display:none}
body.lab-on #fsbar{box-shadow:0 -4px 0 var(--acc) inset}
#toast{position:fixed;bottom:calc(var(--barh) + 12px);left:50%;transform:translate(-50%,15px);opacity:0;background:var(--paper);color:#2a1a10;border-radius:3px;padding:11px 18px;font:13px var(--mono);pointer-events:none;transition:.2s;z-index:12;max-width:90vw;text-align:center;border:1px solid var(--brass3);box-shadow:0 0 0 2px #00a6fb55}#toast.show{opacity:1;transform:translate(-50%,0)}
dialog{z-index:20}
#loading{position:fixed;inset:0;background:var(--bg);z-index:50;display:flex;align-items:center;justify-content:center;flex-direction:column;transition:opacity .5s;color:var(--acc2);padding:0 16px;text-align:center}#loading b{font:700 44px var(--serif);letter-spacing:6px;color:var(--brass2);text-shadow:0 0 22px #00a6fb66}#loading p{font:11px var(--mono);letter-spacing:3px;margin-top:24px}#loading small{font-size:11px;color:#b5a78a;letter-spacing:1.5px}
.lens{position:relative;width:74px;height:74px;margin-bottom:22px;border-radius:50%;border:5px solid var(--brass);background:radial-gradient(circle at 35% 30%,#6fd3ff44,#0b1a24 70%);box-shadow:0 0 30px #00a6fb44,inset 0 0 14px #000;overflow:visible}
.lens::after{content:"";position:absolute;right:-26px;bottom:-22px;width:12px;height:34px;border-radius:6px;background:linear-gradient(90deg,#8a6224,#f3cf7a,#8a6224);transform:rotate(-42deg);transform-origin:top center}
.lens i{position:absolute;left:50%;top:50%;width:14px;height:14px;margin:-7px;border-radius:50%;background:radial-gradient(#fff,#6fd3ff 55%,#00a6fb);box-shadow:0 0 16px #6fd3ff;animation:lensSweep 2.6s ease-in-out infinite}
@media(max-width:760px){#statusLine .src{display:none}.read strong{font-size:20px}.read{padding:0 6px}.spin{min-width:120px;padding:4px 10px}.fb-head{flex:1 1 100%}#fbBody{justify-content:flex-start}.row.main{flex-wrap:wrap}.row.main .spin{flex:1}.deck{min-width:62px}.stepper strong{min-width:34px;font-size:20px}dialog{padding:16px}dialog h2{font-size:26px}.rule-grid{grid-template-columns:repeat(4,1fr)}.lab-list{grid-template-columns:1fr}.side-meters{display:none}.sat-table .hide-s{display:none}#loading b{font-size:32px;letter-spacing:4px}}
@media(max-height:520px){#fsbar{gap:5px;padding-top:8px}.read strong{font-size:19px}.fb-head strong{font-size:16px}.fb-head span:last-child{display:none}.fb-head{min-width:110px;flex:0 1 150px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
